// Parse Lead — synthetic-first, Gmail-compatible
const crypto = require('crypto');
const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  const now = new Date().toISOString();
  const isSynth = Boolean(j.synthetic_fixture || j.fixture_id || j.__synthetic);
  let gmail_message_id = String(j.gmail_message_id || j.id || j.messageId || '').trim();
  if (!gmail_message_id) gmail_message_id = isSynth ? ('msg_synth_' + (j.fixture_id || 'X')) : ('msg_' + crypto.randomUUID());
  const lead_id = String(j.lead_id || ('lead_' + crypto.randomUUID()));
  const text = String(j.request_text || j.text || j.snippet || j.body || '');
  const parsed_name = String(j.parsed_name || j.client_name || j.name || '').trim();
  const parsed_phone = String(j.parsed_phone || j.phone || '').trim();
  const parsed_email = String(j.parsed_email || j.email || '').trim();
  const parsed_messenger = String(j.parsed_messenger || j.messenger || '').trim();
  const parsed_site = String(j.parsed_site || j.site || '').trim();
  const hasContact = Boolean(parsed_phone || parsed_email || parsed_messenger);
  const parse_status = hasContact || text ? (parsed_name || parsed_site || text.length > 10 ? 'ok' : 'partial') : 'failed';
  out.push({
    json: {
      ...j,
      lead_id,
      gmail_message_id,
      gmail_thread_id: j.gmail_thread_id || j.threadId || '',
      received_at: j.received_at || now,
      source: j.source || (isSynth ? 'synthetic' : 'gmail'),
      email_subject: j.email_subject || j.subject || '',
      sender_email: j.sender_email || '',
      request_page: j.request_page || '',
      form_name: j.form_name || '',
      utm_source: j.utm_source || '',
      utm_medium: j.utm_medium || '',
      utm_campaign: j.utm_campaign || '',
      utm_term: j.utm_term || '',
      utm_content: j.utm_content || '',
      parsed_name,
      parsed_phone,
      parsed_email,
      parsed_messenger,
      parsed_site,
      request_text: text.slice(0, 4000),
      calc_detected: String(j.calc_detected || 'false'),
      calc_data: j.calc_data || '',
      ip: j.ip || '',
      parser_version: 'sm-parser-v3',
      parse_status,
      parse_warnings: j.parse_warnings || '',
      workflow_version: 'operational.dev.phase3b',
      raw_logged_at: now,
      raw_text: String(j.raw_text || text).slice(0, 8000),
      __synthetic: isSynth,
      fixture_id: j.fixture_id || null,
    }
  });
}
return out;

const rows = $input.all().map(i => i.json);
const map = {};
for (const r of rows) {
  if (r.key != null) map[String(r.key)] = r.value;
}
const bool = (v, d=false) => {
  if (v === true || v === 'true' || v === '1') return true;
  if (v === false || v === 'false' || v === '0') return false;
  return d;
};
const lead = $('Parse Lead').first().json;
const config = {
  ai_enabled: bool(map.ai_enabled, false),
  ai_model: map.ai_model || '',
  environment: map.environment || 'dev',
  message_format_version: map.message_format_version || 'sm-msg-v1',
  reply_template_version: map.reply_template_version || 'sm-reply-v1',
  parser_version: map.parser_version || 'sm-parser-v3',
  health_ai_probe_enabled: bool(map.health_ai_probe_enabled, false),
  dedupe_contact_window_days: Number(map.dedupe_contact_window_days || 365),
  gmail_query_limit: Number(map.gmail_query_limit || 10),
  stats_days_default: Number(map.stats_days_default || 7),
};
return [{ json: { ...lead, config, ai_enabled: config.ai_enabled } }];

const j = $input.first().json;
const cfg = j.config || {};
const name = String(j.parsed_name || '').trim();
const phone = String(j.parsed_phone || '').trim();
const email = String(j.parsed_email || '').trim();
const messenger = String(j.parsed_messenger || '').trim();
const site = String(j.parsed_site || '').trim();
const text = String(j.request_text || '');
const lower = (text + ' ' + (j.request_page || '') + ' ' + (j.email_subject || '')).toLowerCase();

function detectService() {
  const rules = [
    ['Audit', [/аудит/, /seo-аудит/, /\baudit\b/, /проверка сайта/, /\/audit/]],
    ['SEO', [/\bseo\b/, /продвижен/, /поисковое/, /позиции/, /трафик/, /семантическое ядро/]],
    ['Direct', [/директ/, /контекст/, /яндекс директ/, /\bppc\b/, /реклама в поиске/]],
    ['Site', [/создание сайта/, /разработка сайта/, /лендинг/, /сайт под ключ/, /редизайн/]],
  ];
  for (const [svc, arr] of rules) {
    if (arr.some(re => re.test(lower))) return svc;
  }
  return 'Other';
}

const service = detectService();
const contacts = [phone, email, messenger].filter(Boolean);
const primary_contact = phone || email || messenger || '';
let contact_type = 'unknown';
if (contacts.length > 1) contact_type = 'mixed';
else if (phone) contact_type = 'phone';
else if (email) contact_type = 'email';
else if (messenger) contact_type = 'messenger';

let quality_status = 'ok';
const missing = [];
if (!primary_contact) { quality_status = 'unusable'; missing.push('контакт'); }
else {
  if (!name) missing.push('имя');
  if (!site) missing.push('сайт');
  if (text.length < 40) missing.push('текст заявки');
  if (!name && !site && text.length < 40) quality_status = 'poor';
  else if (!name || !site || text.length < 40) quality_status = 'needs_data';
  else quality_status = 'ok';
}

let priority = 'normal';
if (/срочно|urgent|asap|критич/i.test(text) || (service === 'Audit' && site)) priority = 'high';
if (quality_status === 'unusable' || /информацион/i.test(text)) priority = 'low';

const serviceClause = {
  Audit: ' (запрос по аудиту сайта)',
  SEO: ' (запрос по SEO)',
  Direct: ' (запрос по Директу)',
  Site: ' (запрос по созданию сайта)',
  Other: '',
}[service] || '';

const first_reply_text = name
  ? ('Здравствуйте, ' + name + '!\n\nСпасибо, ваша заявка получена' + serviceClause + '.\nСпециалист свяжется с вами, чтобы уточнить задачу.\n\nС уважением,\nкоманда i-SEO')
  : ('Здравствуйте!\n\nСпасибо, ваша заявка получена' + serviceClause + '.\nМенеджер свяжется с вами, чтобы уточнить задачу.\n\nС уважением,\nкоманда i-SEO');

const clarification_questions = [];
if (!name) clarification_questions.push('Как к вам обращаться?');
if (!site) clarification_questions.push('Укажите, пожалуйста, адрес сайта.');
if (text.length < 40) clarification_questions.push('Кратко опишите задачу и желаемый результат.');

const summary = (text || ('Заявка: ' + service)).replace(/\s+/g, ' ').trim().slice(0, 280);
const quality_comment = quality_status === 'ok' ? 'Данных достаточно'
  : quality_status === 'needs_data' ? 'Нужны уточнения — ' + missing.join('; ')
  : quality_status === 'poor' ? 'Слабые данные'
  : 'Недостаточно для связи';

const manager_recommendation = quality_status === 'unusable'
  ? 'Запросить контакт перед КП.'
  : (missing.length ? ('Уточнить: ' + missing.join(', ') + '; использовать вопросы ниже.') : 'Можно готовить следующий шаг.');

return [{
  json: {
    ...j,
    client_name: name,
    primary_contact,
    contact_type,
    phone, email, messenger, site, service, summary, priority,
    quality_status, quality_comment,
    missing_fields: missing.join('; '),
    clarification_questions: clarification_questions.map((q,i)=>((i+1)+') '+q)).join('\n'),
    manager_recommendation,
    first_reply_text,
    first_reply_source: 'template',
    processing_mode: 'ai_off',
    ai_status: 'skipped',
    fallback_used: false,
    ai_enabled: Boolean(cfg.ai_enabled),
    message_format_version: cfg.message_format_version || 'sm-msg-v1',
    reply_template_version: cfg.reply_template_version || 'sm-reply-v1',
    parser_version: cfg.parser_version || j.parser_version || 'sm-parser-v3',
  }
}];

const j = $input.first().json;
const body = {
  model: (j.config && j.config.ai_model) || 'openai/gpt-4o-mini',
  messages: [{
    role: 'user',
    content: 'Return ONLY JSON with keys summary,service,priority,quality_status,quality_comment,missing_fields,clarification_questions,manager_recommendation,first_reply_text. Lead: ' + JSON.stringify({
      client_name: j.client_name, phone: j.phone, email: j.email, messenger: j.messenger, site: j.site,
      service: j.service, summary: j.summary, request_text: j.request_text, quality_status: j.quality_status
    })
  }],
  response_format: { type: 'json_object' }
};
return [{ json: { ...j, openrouter_body: body } }];

const j = $input.first().json;
let raw = j.choices?.[0]?.message?.content || j.data || j.body || j;
if (typeof raw === 'object' && raw.choices) raw = raw.choices?.[0]?.message?.content;
let parsed = null; let ok = false; let reason = '';
try {
  if (typeof raw === 'string') parsed = JSON.parse(raw);
  else if (raw && typeof raw === 'object') parsed = raw;
  const allowedService = ['Audit','SEO','Direct','Site','Other'];
  const allowedPriority = ['low','normal','high'];
  const allowedQuality = ['ok','needs_data','poor','unusable'];
  if (!parsed || typeof parsed !== 'object') { reason = 'not_object'; }
  else if (!allowedService.includes(parsed.service)) { reason = 'bad_service'; }
  else if (!allowedPriority.includes(parsed.priority)) { reason = 'bad_priority'; }
  else if (!allowedQuality.includes(parsed.quality_status)) { reason = 'bad_quality'; }
  else if (/гарант|фиксированн.*цен|точно за \d|обещаю результат/i.test(String(parsed.first_reply_text||''))) { reason = 'unsafe_promise'; }
  else { ok = true; }
} catch (e) { reason = 'invalid_json'; }
return [{ json: { ...$('Deterministic Lead Processor').first().json, ai_valid: ok, ai_reason: reason, ai_parsed: parsed, ai_raw_present: Boolean(raw) } }];

const det = $('Deterministic Lead Processor').first().json;
const j = $input.first().json;
const fromAI = j.ai_valid && j.ai_parsed ? j.ai_parsed : null;
if (!fromAI) {
  return [{ json: { ...det, processing_mode: det.ai_enabled ? 'ai_fallback' : 'ai_off', ai_status: det.ai_enabled ? 'fallback' : 'skipped', fallback_used: Boolean(det.ai_enabled), first_reply_source: det.ai_enabled ? 'ai_fallback_template' : 'template' } }];
}
return [{ json: {
  ...det,
  summary: fromAI.summary || det.summary,
  service: fromAI.service || det.service,
  priority: fromAI.priority || det.priority,
  quality_status: fromAI.quality_status || det.quality_status,
  quality_comment: fromAI.quality_comment || det.quality_comment,
  missing_fields: Array.isArray(fromAI.missing_fields) ? fromAI.missing_fields.join('; ') : (fromAI.missing_fields || det.missing_fields),
  clarification_questions: Array.isArray(fromAI.clarification_questions) ? fromAI.clarification_questions.map((q,i)=>((i+1)+') '+q)).join('\n') : (fromAI.clarification_questions || det.clarification_questions),
  manager_recommendation: fromAI.manager_recommendation || det.manager_recommendation,
  first_reply_text: fromAI.first_reply_text || det.first_reply_text,
  first_reply_source: 'ai',
  processing_mode: 'ai_on',
  ai_status: 'success',
  fallback_used: false,
}}];

const j = $input.first().json;
const matches = $input.all().map(i => i.json).filter(x => x && (x.dedup_key || x.key_type));
const invalid = new Set(['44', '#error!', '#ERROR!', 'telegram', 'whatsapp', 'viber', 'телефон', 'localhost']);

function normPhone(p){ return String(p||'').replace(/\D/g,''); }
function normEmail(e){ return String(e||'').trim().toLowerCase(); }
function normSite(s){ return String(s||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/\/.*$/,'').replace(/^www\./,''); }
function validPhone(p){ const d=normPhone(p); return d.length>=10 && d.length<=15 && !invalid.has(d) && d !== '44'; }
function validEmail(e){ const v=normEmail(e); return v.includes('@') && v.includes('.') && !invalid.has(v); }
function validSite(s){ const v=normSite(s); return v && !invalid.has(v) && !v.includes(' '); }

const keys = [];
if (j.gmail_message_id) keys.push({key_type:'gmail_message_id', normalized_value:String(j.gmail_message_id).trim()});
if (validPhone(j.phone)) keys.push({key_type:'phone', normalized_value:normPhone(j.phone)});
if (validEmail(j.email)) keys.push({key_type:'email', normalized_value:normEmail(j.email)});
if (validSite(j.site)) keys.push({key_type:'site', normalized_value:normSite(j.site)});
const rejected_keys = [];
for (const cand of [j.phone, j.email, j.site, '44', '#ERROR!']) {
  const s = String(cand||'').trim();
  if (!s) continue;
  if (invalid.has(s.toLowerCase()) || s === '44' || s === '#ERROR!' || normPhone(s)==='44') rejected_keys.push(s);
}

let duplicate_status = 'new';
let duplicate_match_type = 'none';
let duplicate_lead_id = '';
const byType = {};
for (const m of matches) {
  if (String(m.active).toLowerCase() === 'false') continue;
  byType[m.key_type] = m;
}
if (byType.gmail_message_id) {
  duplicate_status = 'reprocessed';
  duplicate_match_type = 'same_message';
  duplicate_lead_id = byType.gmail_message_id.lead_id || '';
} else if (byType.phone || byType.email || byType.messenger) {
  const m = byType.phone || byType.email || byType.messenger;
  duplicate_status = 'repeat';
  duplicate_match_type = m.key_type;
  duplicate_lead_id = m.lead_id || '';
} else if (byType.site) {
  duplicate_status = 'possible';
  duplicate_match_type = 'site_only';
  duplicate_lead_id = byType.site.lead_id || '';
}

const candidate_keys = keys.map(k => ({ ...k, dedup_key: k.key_type + ':' + k.normalized_value }));
return [{ json: { ...j, duplicate_status, duplicate_match_type, duplicate_lead_id, candidate_keys, rejected_invalid_keys: rejected_keys, manager_status: j.manager_status || 'new', reply_review_status: 'draft' } }];

const j = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const dash = (s) => { const v = String(s ?? '').trim(); return v ? esc(v) : '—'; };
const dupMap = { new:'Новый лид', repeat:'Повторный лид', possible:'Возможный повтор (сайт)', reprocessed:'Повторная обработка' };
const qMap = { ok:'Данных достаточно', needs_data:'Нужны уточнения', poor:'Слабые данные', unusable:'Недостаточно для связи' };
const svcMap = { Audit:'Аудит', SEO:'SEO', Direct:'Директ', Site:'Сайт', Other:'Другое' };
const modeMap = { ai_off:'Без AI', ai_on:'AI', ai_fallback:'AI недоступен → шаблон' };
const header = dupMap[j.duplicate_status] || 'Новый лид';
const contactBits = [];
if (j.phone) contactBits.push(esc(j.phone) + ' (телефон)');
if (j.email) contactBits.push(esc(j.email) + ' (email)');
if (j.messenger) contactBits.push(esc(j.messenger) + ' (мессенджер)');
const contacts = contactBits.length ? contactBits.join(', ') : '—';
const utm = [j.utm_source, j.utm_medium, j.utm_campaign].filter(Boolean).map(esc).join(' / ');
const sourceLine = [j.request_page ? esc(j.request_page) : '', utm ? ('utm: ' + utm) : ''].filter(Boolean).join(' · ') || '—';
let text = '';
text += header + '\n\n';
text += 'Клиент: ' + dash(j.client_name) + '\n';
text += 'Контакты: ' + contacts + '\n';
text += 'Сайт: ' + dash(j.site) + '\n';
text += 'Услуга: ' + (svcMap[j.service] || dash(j.service)) + '\n';
text += 'Источник: ' + sourceLine + '\n\n';
text += 'Кратко: ' + dash(j.summary) + '\n\n';
text += 'Чего не хватает: ' + dash(j.missing_fields) + '\n';
text += 'Качество: ' + (qMap[j.quality_status] || dash(j.quality_status)) + (j.quality_comment ? (' — ' + esc(j.quality_comment)) : '') + '\n';
text += 'Следующий шаг: ' + dash(j.manager_recommendation) + '\n\n';
if (j.clarification_questions) {
  text += 'Уточняющие вопросы:\n' + esc(j.clarification_questions) + '\n\n';
}
if (['repeat','possible','reprocessed'].includes(j.duplicate_status)) {
  text += 'История: match=' + esc(j.duplicate_match_type) + '; prior=' + dash(j.duplicate_lead_id) + '\n\n';
}
text += 'Режим обработки: ' + (modeMap[j.processing_mode] || dash(j.processing_mode)) + '\n\n';
text += '——— Скопировать ответ клиенту ———\n';
text += String(j.first_reply_text || '') + '\n';
text += '——— Конец ответа ———\n';
text += 'Отправляется только вручную. Бот клиенту не пишет.\n';
if (j.lead_id) text += '\n#' + String(j.lead_id).slice(0, 12);
return [{ json: { ...j, telegram_text: text, telegram_ok: true } }];

const j = $input.first().json;
// When Telegram node is disabled in sandbox, treat formatted card as success for graph validation only if flag set.
const ok = j.telegram_ok !== false && j.force_telegram_fail !== true;
return [{ json: { ...j, telegram_ok: ok } }];

const j = $input.first().json;
const now = new Date().toISOString();
const error_code = j.error_code || (j.telegram_ok === false ? 'telegram_delivery_failed' : 'processing_error');
const stage = j.error_stage || (j.telegram_ok === false ? 'telegram_send' : 'unknown');
return [{ json: {
  ...j,
  error_code,
  stage,
  error_message: String(j.error_message || j.message || stage).slice(0, 500),
  error_ts: now,
  workflow: 'Operational.dev',
  resolved: false,
  telegram_ok: false,
}}];
